T[9]={entrance={map=1437,x=47.8,y=56.3,zone={en="Portal on the hill southeast of Whelgar's Excavation Site, Wetlands",ko="저습지 웰가르의 발굴현장 남동쪽 언덕 위의 포털"}},instanceIDs={2998},key="excav",levels="26-31",name={de="Ausgrabungsstätte: Sumpfland",en="Excavation Site: Wetlands",es="Excavación: Los Humedales",fr="Excavations : les Paluns",ko="발굴 현장: 저습지",ru="Раскопки: Болотина",zhCN="挖掘场：湿地",zhTW="挖掘場：濕地"},nameMatch={"발굴 현장","Excavation Site","Ausgrabungsstätte: Sumpfland","Excavations : les Paluns","Excavación: Los Humedales","Раскопки: Болотина","挖掘场：湿地","挖掘場：濕地"},quests={{faction="Alliance",giver={en="Return 4 Thicket Raptor Hides to James Halloran, the tanner, in Menethil Harbor.",ko="덤불 랩터 가죽 4장을 메네실 항구의 무두장이 제임스 할로란에게 가져가야 합니다."},id=98815,level=28,minLevel=24,name={en="Highland Hides",ko="고원의 가죽"}},{faction="Alliance",giver={en="Kill a Highland Horror within Excavation Sites and bring its root core to Rethiel the Greenwarden in the Wetlands.",ko="발굴 현장에서 고원 공포를 처치하고 그 뿌리핵을 저습지에 있는 신록의수호자 레시엘에게 가져가야 합니다."},id=95646,level=31,minLevel=24,name={en="Horrors in the Highland",ko="고원의 공포"}},{faction="Alliance",giver={en="Find Ardin Grassman in the Excavation Sites.",ko="발굴 현장에서 아르딘 그래스맨을 찾아야 합니다."},id=95647,level=31,minLevel=24,name={en="Lost in the Thicket Things",ko="덤불 속 실종자"}},{faction="Alliance",giver={en="Bring the Titan Relic to Prospector Whelgar in the Wetlands excavation site. The relic is returned for the follow-up quest; you do not need to collect another.",ko="티탄의 유물을 저습지 발굴현장에 있는 발굴조사단장 웰가르에게 가져가야 합니다. 후속 퀘스트용 유물을 돌려받으므로 다시 구할 필요가 없습니다."},id=95810,level=31,minLevel=24,name={en="Lost Relic Carry",ko="잃어버린 유물 운반"}},{faction="Alliance",giver={en="Look for Dorin Songblade's brother, Daewyn, in Whelgar's Excavation Site.",ko="웰가르의 발굴현장에서 도린 송블레이드의 형제 데윈을 찾아야 합니다."},id=95772,level=31,minLevel=24,name={en="Songblade Search",ko="송블레이드 찾기"}},{faction="Horde",giver={en="Enter the Excavation Sites in the Wetlands and bring back Thicket Raptor Meat.",ko="저습지의 발굴 현장에 들어가 덤불 랩터 고기 4개를 가져와야 합니다."},id=95697,level=31,minLevel=24,name={en="Changing Tastes",ko="달라지는 입맛"}},{faction="Horde",giver={en="Take the Titan Relic to the Elder Rise in Thunder Bluff and look for someone who can tell you more about it. The relic is returned for the follow-up quest; you do not need to collect another.",ko="티탄의 유물을 썬더 블러프의 장로의 봉우리로 가져가 그에 대해 알려 줄 사람을 찾아야 합니다. 후속 퀘스트용 유물을 돌려받으므로 다시 구할 필요가 없습니다."},id=95664,level=31,minLevel=24,name={en="Elder Knowledge",ko="장로의 지식"}},{giver={en="Kill 2 Dragonmaw Saboteurs and 4 Dragonmaw Warders in the Excavation Site and bring back the Dragonmaw Dispatch.",ko="발굴 현장에서 용아귀 파괴공작원 2명과 용아귀 감시병 4명을 처치하고 용아귀 급보를 가져와야 합니다."},id=95682,level=31,minLevel=24,name={en="Open the Maw",ko="용아귀 열기"}}},slug="excavation-site",steps={{id="s1",kind="boss",loot={273022,273023,273024},n="1",name={en="Saltspine",ko="소금가시"},npc={260322}},{id="s2",kind="boss",loot={273025,273027,273106,273026},n="2",name={en="Shadetooth",ko="그늘이빨"},npc={260325}},{id="s3",kind="boss",loot={270180},n="3",name={en="Highland Horror",ko="고원 공포"},npc={260808},quest=true,quests={95646}},{id="s4",kind="boss",loot={273028,273029,273030,273097,270866},n="4",name={en="Relic Guardian",ko="유물 수호자"},npc={260326},quest=true,quests={95664,95810}}}}
T[10]={entrance={map=1421,note={en="The outer sewer gate requires the Dalaran Sewer Key. From inside the city, use the passage beside the Underbelly tavern.",ko="하수도 문은 달라란 하수도 열쇠로 엽니다. 도시 안에서는 하수도의 선술집 옆 통로로 갈 수 있습니다."},x=69.6,y=46.1,zone={en="Dalaran sewer entrance by Lordamere Lake, Silverpine Forest",ko="은빛소나무 숲 로다미어 호수 달라란 하수도 입구"}},instanceIDs={2959},key="dala",levels="28-33",name={de="Dalaran",en="City of Dalaran",es="Ciudad de Dalaran",fr="Cité de Dalaran",ko="달라란",ru="Даларан",zhCN="达拉然城",zhTW="達拉然城"},nameMatch={"달라란","Dalaran","Cité de Dalaran","Ciudad de Dalaran","Даларан","达拉然城","達拉然城"},quests={{faction="Alliance",giver={en="Collect a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City.",ko="달라란에서 지옥 마력이 주입된 꽃을 구해 스톰윈드에 있는 샤이라미르에게 가져가야 합니다."},id=92456,level=33,minLevel=24,name={en="A Green Sample",ko="녹색 표본"},rewards={{id=279835,name={en="Vine Pruner's Cloak",ko="덩굴치기의 망토"}},{id=279836,name={en="Thorn Protecting Girdle",ko="가시막이 요대"}}}},{faction="Alliance",giver={en="Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran. Taking it gives you the Dalaran Sewer Key.",ko="달라란 근처의 대마법사 모데라의 환영를 위해 달라란에서 비전 티끌를 구해야 합니다. 이 퀘스트를 받으면 달라란 하수도 열쇠를 줍니다."},id=92458,level=33,minLevel=24,name={en="Heart of Disruption",ko="분열의 심장"},rewards={{id=279839,name={en="Spellguard Pauldrons",ko="주문수호 견갑"}},{id=279840,name={en="Renewing Footpads",ko="소생의 발보호구"}},{id=279841,name={en="Defender of Dalaran",ko="달라란의 수호자"}}}},{faction="Alliance",giver={en="Slay the Mana Elemental in the City of Dalaran for High Sorcerer Andromath in Stormwind City.",ko="스톰윈드에 있는 고위마술사 안드로매스를 위해 달라란에서 마나 정령을 처치해야 합니다."},id=92489,level=33,minLevel=24,name={en="Power Overwhelming",ko="압도적인 힘"},rewards={{id=251962,name={en="Violet Sash",ko="보랏빛 장식띠"}},{id=279849,name={en="Runebound Gloves",ko="룬결속 장갑"}}}},{faction="Horde",giver={en="Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill. Taking it gives you the Dalaran Sewer Key.",ko="타렌 밀농장에 있는 마법학자 워딘 보이드글레어를 위해 달라란에서 비전 티끌를 구해야 합니다. 이 퀘스트를 받으면 달라란 하수도 열쇠를 줍니다."},id=96984,level=33,minLevel=24,name={en="Heart of Disruption",ko="분열의 심장"},rewards={{id=279842,name={en="Battle Spaulders",ko="전투 어깨덮개"}},{id=279843,name={en="Enchanted Sandals",ko="마력 깃든 덧신"}},{id=279844,name={en="Striking Staff",ko="강타의 지팡이"}}}},{faction="Horde",giver={en="Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance.",ko="하수도 입구 근처에 있는 렉시 코퍼클러치를 위해 달라란에서 달라란 건국사를 구해야 합니다."},id=96987,level=33,minLevel=24,name={en="Opportunistic Education",ko="기회주의 학습법"},rewards={{id=279845,name={en="Solid Gold Band",ko="순금 고리"}},{id=279846,name={en="Larcenist's Belt",ko="절도범의 허리띠"}}}},{faction="Horde",giver={en="Defeat Atrexis the Grave Knight in the City of Dalaran for Melisara in Tarren Mill.",ko="타렌 밀농장에 있는 멜리사라를 위해 달라란에서 무덤 기사 아트렉시스를 쓰러뜨려야 합니다."},id=96986,level=33,minLevel=24,name={en="The Grave Knight",ko="무덤 기사"},rewards={{id=251963,name={en="Gravewalker Boots",ko="무덤걸이 장화"}},{id=251965,name={en="Undead Knight's Bracers",ko="언데드 기사의 팔보호구"}}}},{faction="Horde",giver={en="Collect 6 Cracked Sentry Cores in the City of Dalaran for Doctor Martin Felben in Undercity.",ko="언더시티에 있는 박사 마틴 펠벤을 위해 달라란에서 금이 간 파수꾼 핵 6개를 모아야 합니다."},id=96988,level=33,minLevel=24,name={en="Source of Power",ko="힘의 원천"},rewards={{id=279847,name={en="Unstable Power Core",ko="불안정한 동력 핵"}},{id=279848,name={en="Construct Cloak",ko="피조물 망토"}}}},{giver={en="Defeat 8 Seeking Remnants, 8 Saturated Remnants, and 8 Mana Echoes inside the City of Dalaran for Archmage Modera outside of Dalaran.",ko="달라란 밖에 있는 대마법사 모데라를 위해 달라란 안에서 갈구하는 잔재 8마리, 충만한 잔재 8마리, 마나 메아리 8마리를 처치해야 합니다."},id=92457,level=33,minLevel=24,name={en="Starving Arcane",ko="굶주린 비전"},rewards={{id=279837,name={en="Fallen Guard's Pendant",ko="쓰러진 경비병의 펜던트"}},{id=279838,name={en="Arcane Infused Rod",ko="비전 마력이 주입된 마법막대"}}}}},slug="dalaran",steps={{id="s1",kind="boss",loot={273036,273032,273033},n="1",name