T[11]={entrance={map=1426,x=17.7,y=39.2,zone={en="The front gate of Gnomeregan in western Dun Morogh",ko="던 모로 서쪽 놈리건 정문"}},instanceIDs={90},key="gnomer",levels="29-38",name={de="Gnomeregan",en="Gnomeregan",es="Gnomeregan",fr="Gnomeregan",ko="놈리건",ru="Гномреган",zhCN="诺莫瑞根",zhTW="諾姆瑞根"},nameMatch={"놈리건","Gnomeregan","Гномреган","诺莫瑞根","諾姆瑞根"},quests={{faction="Alliance",giver={en="Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly. Ozzie will also require your Heavy Leaden Collection Phial when the task is complete.",ko="놈리건으로 가서 고농축 방사성 폐기물을 가져와야 합니다. 이 폐기물은 불안정하여 성분이 금방 변할 수 있으니 주의하십시오. 임무를 완수한 후 빈 대형 가연채집병을 오지에게 돌려줘야 합니다."},id=2962,level=30,minLevel=20,name={en="The Only Cure is More Green Glow",ko="유일한 치료법"}},{faction="Alliance",giver={en="Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.",ko="아이언포지에 있는 수석수리공 캐스트파이프에게 오색 천공 카드를 가져가야 합니다."},id=2930,level=30,minLevel=25,name={en="Data Rescue",ko="자료 회수"}},{faction="Alliance",giver={en="Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge.",ko="아이언포지에 있는 클락몰트 스패너스판에게 필수 인공장치 12개를 가져가야 합니다."},id=2924,level=30,minLevel=24,name={en="Essential Artificials",ko="필수 인공장치"}},{faction="Alliance",giver={en="Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.",ko="스톰윈드에 있는 쇼니에게 기계장치 부속품 24개를 가져가야 합니다."},id=2928,level=30,minLevel=20,name={en="Gyrodrillmatic Excavationators",ko="회전천공식 발굴기"}},{faction="Alliance",giver={en="Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.",ko="놈리건으로 가서 멕기니어 텔마플러그를 처치해야 합니다. 임무가 끝나면 땜장이왕 멕카토크에게 돌아와야 합니다."},id=2929,level=35,minLevel=25,name={en="The Grand Betrayal",ko="대배반"}},{faction="Alliance",giver={en="Collect 7 Gnomeregan Archival Data cards from around Gnomeregan, then deliver them to Jemma Quikswitch in Ironforge.",ko="놈리건 전역의 놈리건 보관 자료 카드 7장을 수집한 후, 아이언포지에 있는 젬마 퀵스위치에게 전달해야 합니다."},id=95041,minL